package io.github.ningpp.compat;

import java.util.ResourceBundle;

/**
 * Replacement for System.Resources.ResourceManager (generated by CSharpToJava converter).
 * The generated SR class holds the strings inline, so lookups fall back to the resource
 * bundle when available and otherwise return null (the caller emits "{{name}}").
 */
public class ResourceManager {
    private final String baseName;

    public ResourceManager(String baseName, Object assembly) {
        this.baseName = baseName;
    }

    public ResourceManager(String baseName) {
        this.baseName = baseName;
    }

    /** Mirrors ResourceManager.GetString(string). */
    public String getString(String name) {
        return lookup(name);
    }

    /** Mirrors ResourceManager.GetString(string, CultureInfo). */
    public String getString(String name, CultureInfo culture) {
        return lookup(name);
    }

    private String lookup(String name) {
        try {
            ResourceBundle bundle = ResourceBundle.getBundle(baseName);
            return bundle.containsKey(name) ? bundle.getString(name) : null;
        } catch (Exception e) {
            return null;
        }
    }
}
